// Vertex Story Studio loader. Source: https://github.com/safaothman541-oss/vertex-stories
let vsTimer;
try {
  const m = await Promise.race([
    import("https://cdn.jsdelivr.net/gh/safaothman541-oss/vertex-stories@main/dist/director.js"),
    new Promise((_, no) => { vsTimer = setTimeout(() => no(new Error("timeout after 5 s")), 5000); }),
  ]);
  await m.start(oc);
} catch (e) {
  console.error("[vertex-story] director failed:", e);
  const why = String((e && e.message) || e).replace(/[<>&]/g, " ").slice(0, 200);
  const say = () => {
    const last = oc.thread.messages.at(-1);
    if (last && last.customData && last.customData.vsLoaderError) return;
    oc.thread.messages.push({ author: "system", hiddenFrom: ["ai"], expectsReply: false, customData: { vsLoaderError: true },
      content: "⚠️ دەرهێنەری چیرۆک بار نەبوو، بۆیە دوگمەکانی ▶ ⏭ ⏸ ℹ️ کار ناکەن؛ هێشتا دەتوانیت بە نووسین یاری بکەیت. ئینتەرنێتەکەت بپشکنە و لاپەڕەکە نوێ بکەرەوە. (هۆکار: " + "\u2068" + why + "\u2069)" });
  };
  say();
  oc.thread.on("MessageAdded", ({ message }) => {
    if (!message || message.author !== "user" || !/^\/(play(\s+[0-9٠-٩۰-۹]{1,6})?|next|stop|status)$/i.test(String(message.content).trim())) return;
    message.expectsReply = false;
    message.hiddenFrom = ["ai"];
    say();
  });
} finally {
  clearTimeout(vsTimer);
}
